#!/usr/bin/env bash
# ODEME_VADELERI desktop deploy — shells/kokpit.html'e Vade paneli. Rule 5: build + up. Idempotent.
set -e
cd /opt/krb-assessment
if [ ! -f shells/kokpit.html ]; then echo "HATA: shells/kokpit.html yok"; exit 1; fi
cp shells/kokpit.html shells/kokpit.html.bak.$(date +%s)

echo "== apply desktop patch (shells/kokpit.html) =="
printf '%s' '' | base64 -d > ovdesktop.py
cp ovdesktop.py shells/ovdesktop.py
( cd shells && python3 ovdesktop.py )
rm -f shells/ovdesktop.py

echo "== docker build =="
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment

echo "== verify (beklenen: 1) =="
sleep 4
docker exec krb-assessment grep -c ODEME_VADELERI_DESKTOP_V1 /app/shells/kokpit.html || true
echo "== DONE =="
